mapper.select:
SELECT COUNT(*)
FROM sys_oper_log o
WHERE o.title = '笔记'
  AND o.business_type = 2
  AND o.oper_time >= #{from}
  AND o.oper_time < #{to}

SELECT COUNT(DISTINCT n.update_by)
FROM note_notes n
WHERE n.del_flag = '0'
  AND n.update_by IS NOT NULL
  AND n.update_time >= #{from}
  AND n.update_time < #{to}

SELECT COUNT(*)
FROM sys_login_info l
WHERE l.login_time >= #{from}
  AND l.login_time < #{to}
  AND l.status = '0'

SELECT COUNT(*)
FROM sys_oper_log o
WHERE o.oper_time >= #{from}
  AND o.oper_time < #{to}

SELECT COALESCE(ROUND(100 * SUM(o.status = 0) / NULLIF(COUNT(*), 0), 2), 0)
FROM sys_oper_log o
WHERE o.oper_time >= #{from}
  AND o.oper_time < #{to}
